CREATE OR REPLACE FUNCTION prevent_mutation_append_only()
        RETURNS trigger AS $$
        BEGIN
            RAISE EXCEPTION 'append-only table: % is immutable', TG_TABLE_NAME;
        END;
        $$ LANGUAGE plpgsql;;

